# Good and Bad Tests

## Behavior-facing test

```typescript
test("user can checkout with a valid cart", async () => {
  const cart = createCart();
  cart.add(product);

  const result = await checkout(cart, paymentMethod);

  expect(result.status).toBe("confirmed");
});
```

This test exercises a public capability, describes what matters to a caller, and can survive internal refactoring.

## Implementation-coupled test

```typescript
test("checkout calls paymentService.process", async () => {
  const mockPayment = jest.mock(paymentService);

  await checkout(cart, payment);

  expect(mockPayment.process).toHaveBeenCalledWith(cart.total);
});
```

This test describes internal collaboration. It can fail when implementation changes even if checkout behavior remains correct.

Prefer observing the result through the public interface:

```typescript
test("created user can be retrieved", async () => {
  const user = await createUser({ name: "Alice" });

  const retrieved = await getUser(user.id);

  expect(retrieved.name).toBe("Alice");
});
```

## Tautological test

```typescript
test("calculateTotal sums line items", () => {
  const items = [{ price: 10 }, { price: 5 }];
  const expected = items.reduce((sum, item) => sum + item.price, 0);

  expect(calculateTotal(items)).toBe(expected);
});
```

The expected value repeats the calculation under test. Use an independent known result:

```typescript
test("calculateTotal sums line items", () => {
  expect(calculateTotal([{ price: 10 }, { price: 5 }])).toBe(15);
});
```

# Mocking Boundaries

Mock systems the project does not control. Typical boundaries include external APIs, clocks, randomness, transports, persistent stores, and the filesystem. Prefer a real test store or temporary directory when practical. Exercise project-owned classes and modules through a public boundary instead of mocking their internal collaboration.

Prefer narrow boundary interfaces:

```typescript
function processPayment(order, paymentClient) {
  return paymentClient.charge(order.total);
}
```

Avoid generic boundary wrappers whose mocks need their own routing logic:

```typescript
const api = {
  fetch: (endpoint, options) => fetch(endpoint, options),
};
```

Prefer operation-specific interfaces instead:

```typescript
const api = {
  getUser: (id) => fetch(`/users/${id}`),
  getOrders: (userId) => fetch(`/users/${userId}/orders`),
  createOrder: (data) => fetch("/orders", { method: "POST", body: data }),
};
```

Each mock should represent one external operation with one clear result shape. Assertions should cover project behavior through the chosen seam.

"""Read-only thread hierarchy endpoints.

Threads are projections over existing sessions. Parentage comes from
``thread_delegations``. Every endpoint performs the same session-ownership
check as the existing session APIs before returning data.
"""

import logging
from typing import Any

from fastapi import APIRouter, HTTPException, Request

from yinshi.api.deps import check_session_owner, get_db_for_request
from yinshi.config import get_settings
from yinshi.services.thread_queries import (
    get_thread,
    get_thread_limits,
    get_thread_result,
    get_tree,
    list_children,
)

logger = logging.getLogger(__name__)
router = APIRouter(tags=["threads"])


def _resolve_authorized_thread(
    db: Any,
    session_id: str,
    request: Request,
) -> None:
    """Fail with 404 when the session is missing or not owned."""
    session = db.execute("SELECT id FROM sessions WHERE id = ?", (session_id,)).fetchone()
    if session is None:
        raise HTTPException(status_code=404, detail="Session not found")
    check_session_owner(db, session_id, request)


@router.get("/api/threads/{session_id}")
def get_thread_route(session_id: str, request: Request) -> dict[str, Any]:
    """Return one thread projection."""
    if not get_settings().thread_hierarchy_enabled:
        raise HTTPException(status_code=404, detail="Thread hierarchy is disabled")
    with get_db_for_request(request) as db:
        _resolve_authorized_thread(db, session_id, request)
        return get_thread(db, session_id)


@router.get("/api/threads/{session_id}/children")
def get_thread_children_route(session_id: str, request: Request) -> list[dict[str, Any]]:
    """Return the direct children of a thread."""
    if not get_settings().thread_hierarchy_enabled:
        raise HTTPException(status_code=404, detail="Thread hierarchy is disabled")
    with get_db_for_request(request) as db:
        _resolve_authorized_thread(db, session_id, request)
        return list_children(db, session_id)


@router.get("/api/threads/{session_id}/limits")
def get_thread_limits_route(session_id: str, request: Request) -> dict[str, Any]:
    """Return thread limits plus current usage and remaining allowances."""
    if not get_settings().thread_hierarchy_enabled:
        raise HTTPException(status_code=404, detail="Thread hierarchy is disabled")
    with get_db_for_request(request) as db:
        _resolve_authorized_thread(db, session_id, request)
        return get_thread_limits(db, session_id)


@router.get("/api/threads/{session_id}/result")
def get_thread_result_route(session_id: str, request: Request) -> dict[str, Any]:
    """Return the stored result for a delegated child thread."""
    if not get_settings().thread_hierarchy_enabled:
        raise HTTPException(status_code=404, detail="Thread hierarchy is disabled")
    with get_db_for_request(request) as db:
        _resolve_authorized_thread(db, session_id, request)
        result = get_thread_result(db, session_id)
    if result is None:
        raise HTTPException(status_code=404, detail="Thread result not found")
    return result


@router.get("/api/threads/{session_id}/tree")
def get_thread_tree_route(session_id: str, request: Request) -> dict[str, Any]:
    """Return the bounded thread tree rooted at a session."""
    if not get_settings().thread_hierarchy_enabled:
        raise HTTPException(status_code=404, detail="Thread hierarchy is disabled")
    with get_db_for_request(request) as db:
        _resolve_authorized_thread(db, session_id, request)
        return get_tree(db, session_id)

