    let activeRequests = 0;
    let maximumActiveRequests = 0;
    let requestsStarted = 0;
    const connectEncrypted = vi.fn().mockImplementation(() => {
      let connectionActive = false;
      const connection = {
        request: vi.fn().mockImplementation(async () => {
